import React, { useState } from "react";
import { useDispatch } from "react-redux";
import FormFields from "./FormFields";
import { submitInteraction } from "../../redux/slices/interactionSlice";

const initialFormState = {
  hcp_name: "",
  topics_discussed: "",
  summary: "",
  sentiment: "neutral",
  follow_up_date: "",
  mode: "form",
};

export default function StructuredForm() {
  const dispatch = useDispatch();
  const [formData, setFormData] = useState(initialFormState);
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await dispatch(submitInteraction(formData));
    setSubmitted(true);
    setFormData(initialFormState);
    setTimeout(() => setSubmitted(false), 2500);
  };

  return (
    <form className="card" onSubmit={handleSubmit}>
      <h3>Log a New Interaction</h3>
      <FormFields formData={formData} onChange={handleChange} />
      <button className="btn-primary" type="submit">Save Interaction</button>
      {submitted && <p style={{ color: "#16a34a", marginTop: 10 }}>Saved successfully!</p>}
    </form>
  );
}
